Ltac splitat H k H2 :=
  lazymatch type of H with rw_cells ?sg ?mm ?A0 ?cs =>
    let l1 := spine_firstn k cs in
    let l2 := spine_skipn k cs in
    change (rw_cells sg mm A0 (l1 ++ l2)) in H;
