Lemma sig_ro_CB8 : forall segs m A bs, ro_cells segs m A [CB 8 bs] -> ro_cells segs m A [C8 (le_bytes_to_word bs)].
Proof.
  intros segs m A bs [Hwf Hb]. cbn in Hwf.
  split. { cbn. tauto. }
  cbn [cells_bytes cbytes] in *. rewrite le8_le_bytes_to_word by tauto. exact Hb.
Qed.
Lemma sig_ro_CB4 : forall segs m A bs, ro_cells segs m A [CB 4 bs] -> ro_cells segs m A [C4 (le_bytes_to_word bs)].
Proof.
  intros segs m A bs [Hwf Hb]. cbn in Hwf.
  split. { cbn. tauto. }
  cbn [cells_bytes cbytes] in *.
  assert (E : le4 (le_bytes_to_word bs) = bs).
  { destruct Hwf as [Hl _]. unfold le4, le_bytes_to_word. rewrite Z_to_bv_unsigned.
    change (bv_wrap 64 ?x) with (x mod 2^64).
    rewrite (Mem.Z_to_le_bytes_mod 4 _ 64) by (cbn; lia). rewrite <- Hl. apply Asn1Aux.Z_to_le_bytes_to_Z. }
  rewrite E. exact Hb.
Qed.
