      by (eapply munch_weaken; [| exact Hm]; intros xw Hxw; clear -Hxw; cbn in Hxw |- *; lia);
    let SO := fresh "SOKx" in
    pose proof (statics_ok_munch usegs L _ _ _ SOK MUW ltac:(intros a Ha NW; clear -Ha ACL SLO DHI OD1 OD2; cbn; lia)) as SO;
    let fact off n :=
      let a := eval vm_compute in (U_OID_SIG_ALG_TBL + off) in
      let bs := eval vm_compute in (oidc a n) in
      let H := fresh "TB" in
      pose proof (statics_ok_cells usegs L mx a bs SO
                    ltac:(eapply const_at_sub; [exact CA | vm_compute; intro; discriminate | vm_compute; intro; discriminate])
                    ltac:(vm_compute; reflexivity)) as H;
      cbn [length] in H;
      first [ apply sig_ro_CB8 in H | apply sig_ro_CB4 in H ];
      let k := eval vm_compute in (bv_unsigned (le_bytes_to_word bs)) in
      replace (le_bytes_to_word bs) with (Z_to_bv 64 k) in H by (apply bv_eq; vm_compute; reflexivity) in
    let rec go i :=
      lazymatch eval vm_compute in (i <? 13) with
      | true =>
          let o := eval vm_compute in (40 * i) in
          let o8 := eval vm_compute in (o + 8) in
          let o32 := eval vm_compute in (o + 32) in
          let o36 := eval vm_compute in (o + 36) in
          fact o 8%nat; fact o8 8%nat; fact o32 4%nat; fact o36 4%nat;
          let p := eval vm_compute in (bv_unsigned (le_bytes_to_word (oidc (U_OID_SIG_ALG_TBL + o) 8))) in
          let l := eval vm_compute in (Z.to_nat (bv_unsigned (le_bytes_to_word (oidc (U_OID_SIG_ALG_TBL + o8) 8)))) in
          let R := fresh "RO" in ro_const' p l R;
          let i' := eval vm_compute in (i + 1) in go i'
      | false => fact 520 8%nat
      end in
    go 0
  end end.
