Lemma U_oid_get_sig_alg_spec : ltac2:(CDefT.buildp (gd_tbl_P_oid_sig_alg ()) "PL,$0.(1.$2.R1.$3.$4.+230.+40.)")
(* [comment removed for export] *).
Proof.
  intros L. unfold oid_lookup2_stmt, U_OID_GET_SIG_ALG.
  intros until xs. intros HOID HXS HLEN HE1 HE2 D1 D2 D3 D4 D5 AL1 AL2 AL3 NZ1 NZ2 NZ4 NZ3 ST SLO ACL SPA DS1 DS2 DS4 DS3 MI SOK CA DHI OD1 OD2 -> -> ->.
  pose proof alloc_ceiling_pos as ACP.
  pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR. cbn in SPR.
  pose proof (rw_cells_bound _ _ _ _ HE1) as E1B. cbn [cells_size csize Nat.add Z.of_nat Pos.of_succ_nat Pos.succ] in E1B. change (Z.of_nat 4) with 4 in E1B.
  pose proof (rw_cells_bound _ _ _ _ HE2) as E2B. cbn [cells_size csize Nat.add Z.of_nat Pos.of_succ_nat Pos.succ] in E2B. change (Z.of_nat 4) with 4 in E2B.
  pose proof (rw_cells_bound _ _ _ _ HOID) as OIDB. cbn [cells_size csize Nat.add Z.of_nat Pos.of_succ_nat Pos.succ buf_cells] in OIDB.
  change (Z.of_nat 24) with 24 in OIDB.
  pose proof (bytes_at_bound _ _ _ _ HXS) as PB. rewrite HLEN in PB.
  unfold buf_cells in HOID.
  assert (LEN0 : 0 <= LEN) by lia.
  carve_frame 64%nat ST.
  assert (LXSUMS : forall AL, Forall (summary_ok usegs AL) [SUM_bcmpCP 0x46940])
    by (intros AL; repeat constructor; apply sum_bcmpCP_ok; exact U_bcmp_spec).
  lx_run_tac (PLANS [0x25c5c] [] 60%N (@nil summary)); lx_tree.
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) => rename mx into m1 end.
  lazymatch goal with Hi : mem_inv _ m1 |- _ => rename Hi into MI1 end.
  try clear MI.
  sig_tbl_facts L E1 E2 sp m SOK CA ACL SLO DHI OD1 OD2.
  assert (SEP1 : E1 + 4 <= U_OID_SIG_ALG_TBL \/ U_OID_SIG_ALG_TBL + 560 <= E1) by (destruct CA as (CA1 & CA2 & _); lia).
  assert (SEP2 : E2 + 4 <= U_OID_SIG_ALG_TBL \/ U_OID_SIG_ALG_TBL + 560 <= E2) by (destruct CA as (CA1 & CA2 & _); lia).
  unfold U_OID_SIG_ALG_TBL in SEP1, SEP2.
  lx_run_tac (PLANS [0x25d10] [] 900%N [SUM_bcmpCP 0x46940]); lx_tree.
  all: first [ lxp_at 154896; first [ kdead_pair | kdead ] | lxp_ret ].
Qed.
